<script lang="ts">
 import MeetingDateTime from './MeetingDateTime.svelte';
 import {onMount,onDestroy} from 'svelte';
 import {invoke} from '@tauri-apps/api/core';
 import MailRecipient from './MailRecipient.svelte';
 import MailConfirm from './MailConfirm.svelte';
 import {eventDay,eventWhen,type CalendarEvent} from './calendar';
 import {canReplaceDescription,canManageMeeting,editForm,meetingChanges,manageAttemptKey,type EditableEvent,type EditForm,type MeetingChanges} from './meeting-edit';
 import {receivedText} from './message-body';
 let {ownId,eventId,mode='edit',onClose,onDone}:{ownId:string;eventId:string;mode?:'edit'|'cancel';onClose:()=>void;onDone:(result:{status:string;event?:CalendarEvent})=>void}=$props();
 let event=$state<EditableEvent|null>(null),form=$state<EditForm|null>(null),loading=$state(true),busy=$state(false),error=$state(''),notice=$state(''),attempted=$state(false),review=$state(false),discard=$state(false),comment=$state('');
 let rooms=$state<{emailAddress:string;displayName:string}[]>([]),roomNext=$state<string|null>(null),roomBusy=$state(false),roomError=$state('');
 let alive=true,ready=false,draftKey='';
 const changes=$derived.by(()=>{if(!event||!form)return {};try{return meetingChanges(event,form);}catch{return {};}});
 const reason=$derived.by(()=>{if(!event||!form)return 'Loading meeting…';if(attempted)return 'A change was already attempted for this meeting version. Check Calendar or Outlook before another attempt.';if(mode==='cancel')return '';try{return Object.keys(meetingChanges(event,form)).length?'':'No changes to send.';}catch(e){return e instanceof Error?e.message:String(e);}});
 const roomEditable=$derived((event?.attendees?.filter(a=>a.type==='resource').length??0)<=1&&(event?.locations?.length??0)<=1);
 const currentRoom=$derived(event?.attendees?.find(a=>a.type==='resource'));
 function snapshot(){return {form,comment};}
 onMount(()=>{void (async()=>{try{
  const value=await invoke<EditableEvent>('calendar_manage_read',{eventId});if(!alive)return;if(!canManageMeeting(value))throw Error('Only single meetings you organize can be managed here.');event=value;form=editForm(value);
  draftKey=JSON.stringify(['taut-meeting-edit',ownId,eventId,value.changeKey]);
  attempted=localStorage.getItem(manageAttemptKey(ownId,eventId,value.changeKey!))!==null;
  const stored=localStorage.getItem(draftKey);if(stored){try{if(stored.length>=100000)throw Error('Draft too large');const parsed=JSON.parse(stored);const candidate=parsed.form;if(!candidate||!Object.keys(form).every(k=>typeof candidate[k]===typeof form![k as keyof EditForm]))throw Error('Invalid draft');form=candidate;if(typeof parsed.comment==='string'&&parsed.comment.length<=4000)comment=parsed.comment;}catch{error='Saved draft could not be restored. The current meeting is shown; review your changes again.';}}ready=true;
 }catch(e){if(alive){event=null;form=null;error=String(e);}}finally{if(alive)loading=false;}})();});
 onDestroy(()=>{alive=false;});
 $effect(()=>{const saved=JSON.stringify(snapshot());if(ready&&draftKey){try{localStorage.setItem(draftKey,saved);}catch{error='Draft could not be saved on this device.';}}});
 async function loadRooms(more=false){if(roomBusy)return;roomBusy=true;roomError='';try{const result=await invoke<{value:typeof rooms;next:string|null}>('calendar_rooms',{next:more?roomNext:null});if(alive){rooms=[...new Map([...(more?rooms:[]),...result.value.filter(r=>r.emailAddress)].map(r=>[r.emailAddress,r])).values()];roomNext=result.next;}}catch(e){if(alive)roomError=String(e);}finally{if(alive)roomBusy=false;}}
 async function send(){if(!event||!form||busy||attempted||reason)return;review=false;busy=true;error='';const source=event,patch:MeetingChanges=mode==='edit'?meetingChanges(source,form):{};
  const attempt=manageAttemptKey(ownId,eventId,source.changeKey!);
  try{localStorage.setItem(draftKey,JSON.stringify(snapshot()));localStorage.setItem(attempt,'pending');attempted=true;}catch{error='Cannot safely save this attempt. Nothing was sent.';busy=false;return;}
  try{const result=await invoke<{status:string;event?:CalendarEvent;error?:string}>('calendar_manage',{ownId,eventId,version:source.changeKey,action:mode==='edit'?'update':'cancel',changes:mode==='edit'?patch:null,comment:mode==='cancel'?comment:''});
   if(!alive)return;
   if(result.status==='notSent'){localStorage.removeItem(attempt);attempted=false;error=result.error??'Nothing was sent. Reopen and review the latest meeting.';}
   else if(result.status==='updated'||result.status==='accepted'){localStorage.removeItem(draftKey);ready=false;onDone(result);}
   else notice=result.error??'Change unconfirmed. Check Outlook before trying again.';
  }catch(e){if(alive)notice=`Change unconfirmed. Check Outlook before another attempt. ${String(e)}`;}finally{if(alive)busy=false;}
 }
</script>
<section class="meeting-editor" aria-label={mode==='edit'?'Edit meeting':'Cancel meeting'}>
 <header><div><div class="eyebrow">YOUR MEETING</div><h2>{mode==='edit'?'Edit meeting':'Cancel meeting'}</h2><p>Review and send to update the meeting. Closing does not send.</p>{#if reason}<small class="review-hint">{reason}</small>{/if}</div><div class="editor-actions"><button disabled={busy} onclick={onClose}>Close editor</button><button class="primary" disabled={loading||busy||!event||!form||!!reason} onclick={()=>review=true}>{mode==='edit'?'Review changes':'Review cancellation'}</button></div></header>
 <div class="fields">{#if loading}<p role="status">Loading the latest meeting…</p>{/if}{#if error}<p role="alert">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
 {#if event&&form}<div class="original"><strong>{event.subject||'Untitled meeting'}</strong><p>{eventDay(event)} · {eventWhen(event)}</p><p>Current room: {currentRoom?.emailAddress?.name||currentRoom?.emailAddress?.address||event.location?.displayName||'None'}</p></div>
 {#if mode==='edit'}<fieldset disabled={busy||attempted}>
 <label>Subject<input maxlength="255" bind:value={form.subject}/></label>
 <div class="times"><MeetingDateTime label="Start" precise value={form.start} disabled={event.isAllDay!==false} onChange={value=>{if(form)form.start=value;}}/><MeetingDateTime label="End" precise value={form.end} disabled={event.isAllDay!==false} onChange={value=>{if(form)form.end=value;}}/></div><small>Times are in {Intl.DateTimeFormat().resolvedOptions().timeZone}. All-day times are edited in Outlook.</small>
 <MailRecipient label="Required attendees" value={form.required} {ownId} onFocus={()=>{}} onChange={value=>form&&(form.required=value)}/>
 <MailRecipient label="Optional attendees" value={form.optional} {ownId} onFocus={()=>{}} onChange={value=>form&&(form.optional=value)}/>
 {#if canReplaceDescription(event)}<label>Description<textarea rows="6" maxlength="64000" bind:value={form.description}></textarea></label>{:else}<p class="note">The existing formatted or online-meeting description is preserved.</p><details><summary>Existing description</summary><pre>{receivedText(event.body,event.bodyPreview??'')}</pre></details><label>Add a description note<textarea rows="4" maxlength="4000" bind:value={form.note}></textarea></label>{/if}
 <label class="check"><input type="checkbox" disabled={!roomEditable} checked={form.changeRoom} onchange={e=>{if(form){form.changeRoom=e.currentTarget.checked;if(form.changeRoom)void loadRooms();}}}/>Change room / location</label>
 {#if !roomEditable}<small>Multiple rooms or locations must be changed in Outlook.</small>{/if}
 {#if form.changeRoom}<label>New room<select aria-label="New room" value={form.roomAddress} onchange={e=>{if(form){form.roomAddress=e.currentTarget.value;form.roomName=rooms.find(r=>r.emailAddress===form?.roomAddress)?.displayName||currentRoom?.emailAddress?.name||form.roomAddress;}}}><option value="">No room — clear the location</option>{#if currentRoom?.emailAddress?.address&&!rooms.some(r=>r.emailAddress===currentRoom?.emailAddress?.address)}<option value={currentRoom.emailAddress.address}>{currentRoom.emailAddress.name||currentRoom.emailAddress.address}</option>{/if}{#each rooms as room}<option value={room.emailAddress}>{room.displayName} · {room.emailAddress}</option>{/each}</select></label>{#if roomBusy}<p role="status">Loading rooms…</p>{/if}{#if roomError}<p role="alert">{roomError}</p><button onclick={()=>loadRooms()}>Retry rooms</button>{/if}{#if roomNext}<button onclick={()=>loadRooms(true)}>Load more rooms</button>{/if}<p class="note">A changed room is requested again. It is not booked until the room accepts.</p>{/if}
 </fieldset>{:else}<p class="cancel-warning">This cancels the meeting and sends a cancellation to its attendees and room. It is not just removing your local copy.</p><label>Cancellation note<textarea disabled={busy||attempted} maxlength="4000" rows="5" bind:value={comment}></textarea></label>{/if}
 <footer><button disabled={busy} onclick={()=>discard=true}>Discard local changes</button></footer>{/if}
 </div>
</section>
{#if review&&event&&form}<MailConfirm title={mode==='edit'?'Review meeting changes':'Review meeting cancellation'} confirmLabel={mode==='edit'?'Send meeting update':'Cancel meeting & notify attendees'} cancelLabel="Keep editing" onClose={()=>review=false} onConfirm={send}>
 <p><strong>{event.subject}</strong></p>{#if mode==='edit'}<ul>{#if changes.subject!==undefined}<li>Subject: {event.subject} → {changes.subject}</li>{/if}{#if changes.start}<li>Time: {new Date(changes.start).toLocaleString()} – {new Date(changes.end!).toLocaleString()}</li>{/if}{#if changes.description!==undefined}<li>Replace the plain-text description:<pre class="review-description">{changes.description||'(empty description)'}</pre></li>{/if}{#if changes.descriptionNote}<li>Add note: {changes.descriptionNote}</li>{/if}{#if changes.people}<li>Attendees: {changes.people.map(p=>`${p.address} (${p.kind})`).join('; ')||'None'}</li>{/if}{#if changes.changeRoom}<li>Room / location: {currentRoom?.emailAddress?.name||event.location?.displayName||'None'} → {changes.room?.displayName||'None (location cleared)'}</li>{/if}</ul><p>This updates the existing meeting. Microsoft 365 can notify attendees of the changes. Any new room must accept its booking.</p>{:else}<p>{eventDay(event)} · {eventWhen(event)}</p><p>Room: {currentRoom?.emailAddress?.name||currentRoom?.emailAddress?.address||event.location?.displayName||'None'}</p><p>Cancel this meeting for everyone, including any room resource. Microsoft 365 will send cancellation messages and move the organizer's event to Deleted Items.</p>{#if comment}<blockquote>{comment}</blockquote>{/if}{/if}
</MailConfirm>{/if}
{#if discard}<MailConfirm title="Discard local meeting changes?" confirmLabel="Discard local changes" onClose={()=>discard=false} onConfirm={()=>{if(draftKey)localStorage.removeItem(draftKey);ready=false;onClose();}}><p>This removes only the local editor draft. It does not undo any update or cancellation already submitted.</p></MailConfirm>{/if}
<style>
.meeting-editor{flex:1;min-width:0;overflow:auto;color:var(--text-primary)}header{position:sticky;top:0;z-index:3;display:flex;flex-wrap:wrap;justify-content:space-between;align-items:center;gap:20px;padding:28px;background:var(--surface-panel);border-bottom:1px solid var(--border)}h2{margin:8px 0;font-size:27px}.eyebrow{font-size:10px;letter-spacing:2px;color:var(--accent)}p,small{line-height:1.7}.fields{padding:28px;max-width:850px;margin:auto;display:grid;gap:18px}fieldset{border:0;margin:0;padding:0;display:grid;gap:18px;min-width:0}label{display:grid;gap:8px;font-size:13px}.times{display:grid;grid-template-columns:1fr 1fr;gap:18px}input,textarea,select,button{font:inherit;border:1px solid var(--border-strong);border-radius:8px;background:var(--surface-panel);color:var(--text-primary);padding:11px 14px}input,textarea,select{width:100%;box-sizing:border-box}button{cursor:pointer}button:disabled{opacity:.5;cursor:default}.primary{background:var(--accent);color:var(--text-on-accent)}footer{display:flex;justify-content:space-between;gap:16px}.note,small{font-size:12px;color:var(--text-secondary)}.original{padding:16px 20px;border:1px solid var(--border);border-radius:10px;background:var(--surface-raised)}.original p{font-size:13px;margin:8px 0 0}.cancel-warning{padding:18px;border:1px solid var(--error-border);border-left:4px solid var(--error-border);border-radius:10px;color:var(--error);background:var(--error-surface)}.check{display:flex;align-items:center;gap:10px}.check input{width:auto}.review-description{border-left:2px solid var(--border-strong);padding-left:12px}pre{white-space:pre-wrap;max-height:200px;overflow:auto;font:inherit;font-size:12px}[role=alert]{color:var(--error)}input:focus-visible,textarea:focus-visible,select:focus-visible,button:focus-visible{outline:2px solid var(--accent);outline-offset:3px}:global(.meeting-editor .recipient){display:block;margin:0}:global(.meeting-editor .recipient label){display:block;margin-bottom:8px}
.editor-actions{display:flex;gap:10px;flex-wrap:wrap;margin-left:auto}.review-hint{display:block;max-width:560px}header p{font-size:13px;color:var(--text-secondary);margin:8px 0}</style>
